.fi-ta-content.fi-ta-content-grid{gap:14px!important;padding:16px!important;background:#f5f4ef}.fi-ta-record-content{padding:16px!important}.fi-ta-grid{gap:10px 14px!important}.fi-ta-record-content-ctn{display:flex!important;flex-direction:column!important;height:100%}.fi-ta-record-content-ctn>div:first-child{flex:1;min-width:0}.fi-ta-record .fi-ta-actions{padding:10px 16px!important;border-top:1px solid #eeebe3;background:#fbfaf7;border-radius:0 0 20px 20px}.fi-ta-record .fi-ta-text{font-size:13px}.fi-ta-text-item{white-space:normal;overflow-wrap:anywhere}.fi-ta-text-description{font-size:11px;color:#82765e;letter-spacing:.3px}.fi-ta-record .fi-ta-actions{flex-wrap:wrap;gap:8px}.fi-ta-header-toolbar{flex-wrap:wrap;gap:12px}.fi-ta-search-field{min-width:0;max-width:100%}
